import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DxEvSMU4.js";const m=JSON.parse('{"title":"K4 模型與軟體授權判讀","description":"","frontmatter":{},"headers":[],"relativePath":"know/k4-licenses.md","filePath":"know/k4-licenses.md","lastUpdated":1793028937000}'),i={name:"know/k4-licenses.md"};function o(l,e,d,s,c,g){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="k4-模型與軟體授權判讀" tabindex="-1">K4 模型與軟體授權判讀 <a class="header-anchor" href="#k4-模型與軟體授權判讀" aria-label="Permalink to &quot;K4 模型與軟體授權判讀&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: TAIDE 授權條款全文 (Hugging Face 頁面須登入同意後才能閱讀, 本輪未讀); Gemma 4 授權檔原文 (本輪依 Google 開源部落格與 Gemma 條款頁的指引, 未直接讀授權檔); NVIDIA Open Model License 與 Mistral AI Research License 的要點為整理者依授權全文歸納, 非逐條對照; 模型範例已更換, 授權標示須對照各模型的 Hugging Face 頁面; 量化或轉檔版本是否沿用原模型授權為推論; 本章不構成法律意見; 文中的類比為整理者所寫, 不代表技術或法律上完全等同</li></ul></div><p><strong>結論</strong>: 模型與軟體的授權各自獨立, 要分開檢查. 模型授權分兩類: Apache 2.0, MIT 這類通用開源授權, 以及 Llama, Gemma (Gemma 4 以前), NVIDIA Nemotron, Mistral Large, TAIDE 這類自訂授權; 後者常附使用政策, 標示, 規模門檻或用途限制. 軟體則要分清楚 OSI 開源與「原始碼公開」: n8n, Open WebUI, Dify 的原始碼都看得到, 但授權對使用方式設有限制. 個人與內部使用通常不受影響, 一旦對外提供服務, 最嚴格的條款決定能做什麼 (信心: 中). 每個模型入庫時就把授權記下來 (見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>), 之後才查得到.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>授權 (license)</td><td>著作權人允許別人怎麼使用作品的條件</td></tr><tr><td>權重</td><td>模型訓練出來的大量數字, 也就是模型檔本身 (見 <a href="/lanai-handbook/know/k1-basics">K1</a>)</td></tr><tr><td>OSI 開源</td><td>符合 Open Source Initiative 開源定義的授權, 不得限制使用的人或用途</td></tr><tr><td>原始碼公開 (source-available)</td><td>原始碼看得到, 但授權對使用方式設有限制</td></tr><tr><td>自訂授權</td><td>模型或軟體發布者自己撰寫的授權條款, 例如 Llama, Gemma Terms of Use</td></tr><tr><td>gated model</td><td>須先登入並同意條款才能下載的模型</td></tr><tr><td>AGPL</td><td>一種開源授權, 透過網路提供修改版服務時也要提供原始碼</td></tr><tr><td>散布</td><td>把軟體或模型檔交給組織以外的人, 例如公開下載或隨產品出貨</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><p>本章說明判讀方法; 各元件的授權明細見<a href="/lanai-handbook/ref/licenses">授權速查</a>, 對外服務前的檢查清單見<a href="/lanai-handbook/decide/license-flags">授權紅旗</a>. 授權條款會改版, 正式使用前請以各專案的授權原文為準, 有疑義時請洽法律顧問.</p><h2 id="k4-1-模型授權-通用開源授權與自訂授權" tabindex="-1">K4.1 模型授權: 通用開源授權與自訂授權 <a class="header-anchor" href="#k4-1-模型授權-通用開源授權與自訂授權" aria-label="Permalink to &quot;K4.1 模型授權: 通用開源授權與自訂授權&quot;">​</a></h2><p>授權可以想成租屋契約: 房子 (模型) 可以住, 但契約會寫明能不能轉租, 能不能拿來開店, 門口要不要掛房東指定的招牌. 免費下載不代表沒有條件, 條件都寫在授權裡.</p><p>模型的權重也有授權. 同一個模型家族的不同尺寸或不同世代, 授權可能不同, 因此要逐一看模型頁面, 不能只看家族名稱. 例如 Hugging Face 上 Mistral-7B-Instruct-v0.3 標示 Apache 2.0, 同一家公司的 Mistral-Large-Instruct-2411 標示 <code>mrl</code> (Mistral AI Research License), 模型頁說明只允許非商業的使用與修改 (來源: 各模型的 Hugging Face 頁面).</p><table tabindex="0"><thead><tr><th>類型</th><th>代表</th><th>主要義務與限制</th></tr></thead><tbody><tr><td>Apache 2.0</td><td>Mistral-7B-Instruct-v0.3, gpt-oss-20b, Gemma 4</td><td>散布時附授權副本, 修改過的檔案須標示, 保留 NOTICE 檔; 授權含專利授權, 對該作品提起專利訴訟者的專利授權終止 (來源: Apache License 2.0 第 3, 4 條)</td></tr><tr><td>MIT</td><td>常見於軟體, 模型較少</td><td>所有副本須保留著作權聲明與授權聲明; 不提供任何擔保 (來源: OSI 的 MIT 授權全文)</td></tr><tr><td>Llama 4 Community License</td><td>Llama 4 系列</td><td>前一個月月活躍使用者超過 7 億須另向 Meta 申請授權; 散布時須明顯標示「Built with Llama」; 以 Llama 建立或改良並散布的模型, 名稱開頭須加「Llama」; Acceptable Use Policy 納入合約 (來源: Llama 4 Community License, 2025-04-05 生效)</td></tr><tr><td>Gemma Terms of Use</td><td>Gemma 4 以前的 Gemma 模型, EmbeddingGemma</td><td>不得用於 Prohibited Use Policy 列出的用途; 散布時須把使用限制寫入下游合約, 附條款副本與 Notice 檔; Google 保留遠端或以其他方式限制違規使用的權利 (來源: Gemma Terms of Use, 2026-04-01 修訂)</td></tr><tr><td>NVIDIA Open Model License</td><td>NVIDIA-Nemotron-Nano-9B-v2</td><td>授予永久, 全球, 非專屬, 免費, 免權利金的使用, 修改, 散布與銷售授權; 散布時附授權副本, 並在 Notice 檔寫明「Licensed by NVIDIA Corporation under the NVIDIA Open Model License」; 繞過模型內的安全護欄 (guardrail) 又未採取相當的替代護欄時, 授權自動終止; 對該模型或衍生模型提起著作權或專利侵權訴訟者, 該模型的授權終止; 條文未設使用者數或營收門檻; NVIDIA 可更新條款, 使用者須遵守新版或停止使用 (來源: NVIDIA Open Model License, 2025-10-24 版)</td></tr><tr><td>Mistral AI Research License</td><td>Mistral-Large-Instruct-2411</td><td>使用範圍限於 Research Purposes, 即個人, 科學或學術研究, 且為非營利, 非商業; 條文明列公司員工或外包人員的日常工作使用, 任何以營收為目的的活動 (含測試與 PoC), 以及商業單位提供的託管服務, 都不屬於研究用途; 其他用途須另向 Mistral AI 申請授權, 由其自行決定是否核發 (來源: Mistral AI Research License MRL-0.1 第 3.2 條與定義)</td></tr><tr><td>其他自訂授權</td><td>TAIDE</td><td>條文各不相同, 須逐份閱讀; TAIDE 模型頁面標示「(Gemma 版次)-TAIDE 模型授權條款」, 須登入並同意條款才能下載 (來源: TAIDE Hugging Face 模型頁)</td></tr></tbody></table><p>Gemma 是授權會變動的例子. Google 開源部落格說明 Gemma 4 是 Gemma 系列中第一批以 OSI 認可的 Apache 2.0 授權發布的模型; Gemma 條款頁則註明 Gemma 4 的條款另見 Gemma 4 授權, 不適用 Gemma Terms of Use (來源: Google Open Source Blog, Gemma Terms of Use). 因此, 舊版 Gemma 與 Gemma 4 要分開登記授權.</p><p>自訂授權的共同特徵是附帶使用政策, 標示要求, 規模門檻或用途限制. 這些條款對內部使用的影響多半有限 (研究用途限定的授權除外, 例如 Mistral AI Research License 不含公司員工的日常工作使用), 但在對外提供服務, 散布微調後模型, 或替衍生模型命名時就會出現 (推論, 信心: 中).</p><p><strong>對應架構圖</strong>: 雲端的 Hugging Face 等模型來源; 授權是入庫檢查要記錄的欄位之一.</p><h2 id="k4-2-權重來源與檔案格式決定信任程度" tabindex="-1">K4.2 權重來源與檔案格式決定信任程度 <a class="header-anchor" href="#k4-2-權重來源與檔案格式決定信任程度" aria-label="Permalink to &quot;K4.2 權重來源與檔案格式決定信任程度&quot;">​</a></h2><p>下載模型和下載軟體一樣, 要先看來源. 同一款軟體可以從官網下載, 也可能出現在來路不明的下載站; 模型也是如此, 而且模型檔在某些格式下, 載入時就會執行程式.</p><p>同一個模型可能有官方發布, 社群轉檔, 社群量化等多個版本. 信任程度由高到低大致是: 官方組織帳號發布的原始權重, 知名發布者的轉檔或量化版本, 來源不明的上傳 (信心: 中高, 屬一般經驗).</p><p>判斷來源時可以看三件事:</p><ul><li><strong>發布者</strong>: 是否為模型開發者的官方組織帳號. Hugging Face 文件建議只從可信的使用者與組織載入檔案 (來源: Hugging Face 文件 Pickle scanning).</li><li><strong>衍生關係</strong>: 模型卡的 <code>base_model</code> 欄位標示衍生自哪個模型, <code>base_model_relation</code> 可標示為 <code>finetune</code>, <code>adapter</code>, <code>quantized</code> 或 <code>merge</code> (來源: Hugging Face 文件 Model cards). 量化或轉檔版本的授權應回到原模型確認; 轉檔不會讓授權變寬鬆 (推論, 信心: 中).</li><li><strong>存取條件</strong>: 部分模型是 gated model, 使用者要先同意與作者分享聯絡資訊才能下載; 作者可設為人工核准, 也可隨時撤銷存取 (來源: Hugging Face 文件 Gated models). Llama 3.1 等模型即採此方式 (來源: meta-llama/Llama-3.1-8B-Instruct 模型頁).</li></ul><p>檔案格式也影響風險. pickle 是 Python 用來儲存資料物件的格式; pickle 格式 (常見副檔名 <code>.bin</code>, <code>.pt</code>) 在載入時可以執行任意 Python 程式; Hugging Face 會掃描上傳的 pickle 檔並標示可疑的 import, 但官方自承掃描「並非百分之百可靠」, 使用者須自行確認 (來源: Hugging Face 文件 Pickle scanning). 因此優先選用 safetensors 或 GGUF, 避免來源不明的 pickle 檔. 入庫掃描與雜湊紀錄的做法見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>.</p><p><strong>對應架構圖</strong>: 雲端模型來源到入庫檢查主機 (ModelAudit 等) 的那一段.</p><h2 id="k4-3-osi-開源與「原始碼公開」的差異" tabindex="-1">K4.3 OSI 開源與「原始碼公開」的差異 <a class="header-anchor" href="#k4-3-osi-開源與「原始碼公開」的差異" aria-label="Permalink to &quot;K4.3 OSI 開源與「原始碼公開」的差異&quot;">​</a></h2><p>開源與原始碼公開的差別, 可以想成兩種公開的食譜: 一種公開後任何人都能拿去開店販售; 另一種雖然也公開, 但只准在家裡煮, 或開店前要先取得同意. 兩種都看得到食譜, 能做的事卻不同.</p><p>OSI (Open Source Initiative) 的開源定義要求授權不得歧視任何人或團體, 也不得限制在特定領域使用; 授權也不得限制任何人販售或贈送軟體 (來源: The Open Source Definition 第 1, 5, 6 條). 只要授權對使用方式或對象設限, 即使原始碼公開, 也不屬於 OSI 開源. 本手冊對這類專案稱「原始碼公開」(source-available), 不稱「開源」.</p><p>判斷方式: 讀授權檔, 找有沒有「僅限內部使用」, 「不得營運多租戶服務」, 「超過多少使用者須保留品牌」這類使用限制. 有任一項, 就歸為原始碼公開 (信心: 中高).</p><table tabindex="0"><thead><tr><th>元件</th><th>授權性質</th><th>主要限制</th></tr></thead><tbody><tr><td>n8n</td><td>原始碼公開 (Sustainable Use License; 檔名含 <code>.ee.</code> 的原始碼另屬 n8n Enterprise License)</td><td>只能用於自己的內部業務, 非商業或個人用途; 只能以免費且非商業的方式散布. 官方自述「開源授權不能限制使用方式, 因此我們不稱自己為開源」</td></tr><tr><td>Open WebUI</td><td>原始碼公開 (BSD-3 加品牌條款, v0.6.6 起)</td><td>任一 30 天內使用者超過 50 人時, 不得修改, 移除或遮蔽「Open WebUI」品牌; 例外為取得企業授權或書面許可. 官方說明此授權未經 OSI 認可</td></tr><tr><td>Dify</td><td>原始碼公開 (以 Apache 2.0 修改, 授權名稱為 Dify Open Source License)</td><td>未經書面授權不得以原始碼營運多租戶環境 (一個 workspace 為一個租戶); 使用前端時不得移除或修改主控台與應用程式中的 LOGO 與著作權資訊</td></tr><tr><td>LM Studio</td><td>閉源 (專有軟體)</td><td>軟體屬公司所有, 授權不是出售, 禁止反向工程; 2025 年 7 月起在家與工作使用都免費, 不必填表申請; 部分功能可能收費</td></tr></tbody></table><p>來源: n8n 文件 Sustainable Use License 與 Community license; Open WebUI 文件 License; Dify 儲存庫 LICENSE; LM Studio 部落格 (2025-07-08) 與 App Terms of Use (2026-08-23 版).</p><p>Dify 的授權名稱含「Open Source」, 但條文對使用方式設限, 依 OSI 定義屬原始碼公開 (推論, 信心: 中高). 這也說明判讀時要看條文, 不看名稱.</p><p>n8n 官方 FAQ 對「內部業務」的界線有具體說明: 顧問在自己的 n8n 執行個體上替客戶建立並執行工作流程, 可以收費, 客戶取得的是結果而不是 n8n 的存取權; 讓客戶在自己架設的 n8n 上自行建立工作流程, 則不在社群授權範圍內 (來源: n8n 文件 License FAQ). 本手冊的 M9 只把 n8n 用於內部自動化, 不受此限制 (信心: 中高).</p><p><strong>對應架構圖</strong>: 入口區的 Open WebUI 與自動化區的 n8n 屬原始碼公開; 其他元件的歸類見<a href="/lanai-handbook/ref/licenses">授權速查</a>.</p><h2 id="k4-4-授權疊加-最嚴格的條款決定能做什麼" tabindex="-1">K4.4 授權疊加: 最嚴格的條款決定能做什麼 <a class="header-anchor" href="#k4-4-授權疊加-最嚴格的條款決定能做什麼" aria-label="Permalink to &quot;K4.4 授權疊加: 最嚴格的條款決定能做什麼&quot;">​</a></h2><p>授權疊加可以想成一趟要轉乘好幾段交通工具的旅程: 每一段的行李規定都要遵守, 最後能帶多少行李, 由規定最嚴的那一段決定.</p><p>一套系統由多個元件與模型組成時, 每一份授權都要同時遵守, 因此限制最多的那一份決定整套系統能做什麼 (信心: 中). 同一個專案內也可能有多份授權, 例如 n8n 的 <code>.ee.</code> 檔案, LiteLLM 的 <code>enterprise/</code> 目錄 (見<a href="/lanai-handbook/ref/licenses">授權速查</a>).</p><p>三種使用情境的差異如下 (整理者推論, 信心: 中):</p><table tabindex="0"><thead><tr><th>情境</th><th>通常受影響的條款</th><th>判讀重點</th></tr></thead><tbody><tr><td>個人使用</td><td>很少</td><td>模型的使用政策 (Llama AUP, Gemma Prohibited Use Policy) 仍然適用</td></tr><tr><td>組織內部使用</td><td>品牌與人數門檻, 研究用途限定</td><td>Open WebUI 超過 50 人須保留品牌; LM Studio 的授權範圍為個人與內部業務用途; Mistral AI Research License 的模型不得用於公司日常工作</td></tr><tr><td>對外提供服務或散布</td><td>大多數限制都在這裡出現</td><td>n8n 不得讓客戶在自架環境自建工作流程; Dify 多租戶限制; Llama 7 億月活躍使用者門檻與「Built with Llama」標示; Gemma 下游合約義務; AGPL 元件須提供原始碼</td></tr></tbody></table><p>AGPL 值得單獨留意. AGPL v3 第 13 條要求: 修改過的程式若讓使用者透過網路與它互動, 須明顯提供這些使用者取得對應原始碼的機會 (來源: OSI 的 AGPL v3 全文). 換句話說, 不散布軟體, 只透過網路提供服務, 也可能觸發開放原始碼的義務. 例如 LibreChat 的管理面板採 AGPL (見<a href="/lanai-handbook/ref/licenses">授權速查</a>).</p><p>因應方向: 對外提供服務前, 先依<a href="/lanai-handbook/decide/license-flags">授權紅旗</a>列出所有元件與模型; 有限制的元件優先找授權較寬鬆的替代品, 其次才評估商業授權.</p><p><strong>對應架構圖</strong>: 整張圖. 對外服務時, 入口區 (Open WebUI), 自動化區 (n8n) 與推論區載入的模型是最常出現限制的位置 (推論, 信心: 中).</p><h2 id="k4-5-入庫時記錄授權" tabindex="-1">K4.5 入庫時記錄授權 <a class="header-anchor" href="#k4-5-入庫時記錄授權" aria-label="Permalink to &quot;K4.5 入庫時記錄授權&quot;">​</a></h2><p>入庫時記錄授權, 可以想成購物時保存收據與當時的條款: 日後條款改版, 仍能證明取得時適用的是哪一版.</p><p>授權會改版, 模型頁面也可能更新, 因此要在入庫當下記錄當時的授權. Hugging Face 模型庫以模型卡 (README.md) 開頭的 YAML 中介資料 <code>license</code> 欄位標示授權, 例如 <code>apache-2.0</code>, <code>mit</code>, <code>llama3.1</code>, <code>gemma</code>; 自訂授權標為 <code>license: other</code>, 以 <code>license_name</code> 命名, 並把全文放在模型庫的 <code>LICENSE</code> 檔 (來源: Hugging Face 文件 Licenses).</p><p>建議在 M1.5 節的登記表之外, 為授權補充下列欄位:</p><table tabindex="0"><thead><tr><th>欄位</th><th>內容</th></tr></thead><tbody><tr><td>授權識別碼</td><td>模型卡 <code>license</code> 欄位的值</td></tr><tr><td>授權原文</td><td>下載當下的 <code>LICENSE</code> 檔或授權頁, 存一份副本並記錄雜湊值</td></tr><tr><td>取得日期</td><td>用於日後比對授權是否改版</td></tr><tr><td>原模型</td><td>量化或轉檔版本填 <code>base_model</code>, 並以原模型的授權為準</td></tr><tr><td>是否 gated</td><td>是否須同意條款才能下載, 同意的帳號</td></tr><tr><td>使用範圍</td><td>個人, 內部, 對外; 對外時註明已檢查的限制</td></tr></tbody></table><p>軟體元件也用同樣方式記錄, 版本與授權變動放在<a href="/lanai-handbook/ref/versions">版本頁</a>追蹤 (見 <a href="/lanai-handbook/ops/versioning">O2</a>).</p><p><strong>對應架構圖</strong>: 入庫檢查主機與 NAS 上的模型存放區, 組裝見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://opensource.org/osd" target="_blank" rel="noreferrer">The Open Source Definition (OSI)</a></li><li><a href="https://www.apache.org/licenses/LICENSE-2.0" target="_blank" rel="noreferrer">Apache License 2.0</a></li><li><a href="https://opensource.org/license/mit" target="_blank" rel="noreferrer">MIT License (OSI)</a></li><li><a href="https://opensource.org/license/agpl-v3" target="_blank" rel="noreferrer">GNU AGPL v3 (OSI)</a></li><li><a href="https://dev.meta.ai/llama/llama4/license" target="_blank" rel="noreferrer">Llama 4 Community License Agreement</a></li><li><a href="https://ai.google.dev/gemma/terms" target="_blank" rel="noreferrer">Gemma Terms of Use</a></li><li><a href="https://opensource.googleblog.com/2026/03/gemma-4-expanding-the-gemmaverse-with-apache-20.html" target="_blank" rel="noreferrer">Google Open Source Blog: Gemma 4: Expanding the Gemmaverse with Apache 2.0</a></li><li><a href="https://www.nvidia.com/en-us/agreements/enterprise-software/nvidia-open-model-license/" target="_blank" rel="noreferrer">NVIDIA Open Model License Agreement</a></li><li><a href="https://mistral.ai/static/licenses/MRL-0.1.md" target="_blank" rel="noreferrer">Mistral AI Research License (MRL-0.1)</a></li><li><a href="https://huggingface.co/mistralai/Mistral-7B-Instruct-v0.3" target="_blank" rel="noreferrer">Hugging Face: mistralai/Mistral-7B-Instruct-v0.3</a></li><li><a href="https://huggingface.co/mistralai/Mistral-Large-Instruct-2411" target="_blank" rel="noreferrer">Hugging Face: mistralai/Mistral-Large-Instruct-2411</a></li><li><a href="https://huggingface.co/nvidia/NVIDIA-Nemotron-Nano-9B-v2" target="_blank" rel="noreferrer">Hugging Face: nvidia/NVIDIA-Nemotron-Nano-9B-v2</a></li><li><a href="https://huggingface.co/google/embeddinggemma-300m" target="_blank" rel="noreferrer">Hugging Face: google/embeddinggemma-300m</a></li><li><a href="https://huggingface.co/openai/gpt-oss-20b" target="_blank" rel="noreferrer">Hugging Face: openai/gpt-oss-20b</a></li><li><a href="https://huggingface.co/taide/Gemma-3-TAIDE-12b-Chat-2602" target="_blank" rel="noreferrer">Hugging Face: taide/Gemma-3-TAIDE-12b-Chat-2602</a></li><li><a href="https://huggingface.co/meta-llama/Llama-3.1-8B-Instruct" target="_blank" rel="noreferrer">Hugging Face: meta-llama/Llama-3.1-8B-Instruct</a></li><li><a href="https://huggingface.co/docs/hub/security-pickle" target="_blank" rel="noreferrer">Hugging Face 文件: Pickle scanning</a></li><li><a href="https://huggingface.co/docs/hub/model-cards" target="_blank" rel="noreferrer">Hugging Face 文件: Model cards (base_model)</a></li><li><a href="https://huggingface.co/docs/hub/models-gated" target="_blank" rel="noreferrer">Hugging Face 文件: Gated models</a></li><li><a href="https://huggingface.co/docs/hub/repositories-licenses" target="_blank" rel="noreferrer">Hugging Face 文件: Licenses</a></li><li><a href="https://docs.n8n.io/n8n-community-license/sustainable-use-license" target="_blank" rel="noreferrer">n8n 文件: Sustainable Use License</a></li><li><a href="https://docs.n8n.io/n8n-community-license" target="_blank" rel="noreferrer">n8n 文件: Community license</a></li><li><a href="https://docs.n8n.io/n8n-community-license/community-license/license-faq" target="_blank" rel="noreferrer">n8n 文件: License FAQ</a></li><li><a href="https://docs.openwebui.com/license" target="_blank" rel="noreferrer">Open WebUI 文件: License</a></li><li><a href="https://github.com/langgenius/dify/blob/main/LICENSE" target="_blank" rel="noreferrer">Dify 儲存庫 LICENSE</a></li><li><a href="https://www.lmstudio.ai/blog/free-for-work" target="_blank" rel="noreferrer">LM Studio 部落格: LM Studio is free for use at work</a></li><li><a href="https://lmstudio.ai/app-terms" target="_blank" rel="noreferrer">LM Studio App Terms of Use</a></li><li>文中的類比 (租屋契約, 兩種公開的食譜, 轉乘的行李規定, 保存收據): 整理者所寫, 無外部來源, 不應當作技術或法律定義引用.</li></ul>',45)])])}const p=t(i,[["render",o]]);export{m as __pageData,p as default};
